style.css:
/* Blue Theme for Stylish */
body {
    background-color: #1E90FF; /* Dodger blue for a vibrant feel */
    color: #FFFFFF; /* White text for contrast */
    font-family: 'Arial', sans-serif;
}

/* Subtle gradient effect */
body {
    background: linear-gradient(135deg, #1E90FF, #87CEFA); /* Dodger Blue to Light Sky Blue */
}

/* Links */
a {
    color: #FFD700; /* Gold for a nice contrast */
    text-decoration: none;
}

a:hover {
    color: #FFA500; /* Orange shade for hover effect */
    text-shadow: 0 0 5px #FFFFFF; /* Gentle glow */
}

/* Buttons */
button {
    background-color: #4682B4; /* Steel blue */
    border: none;
    padding: 10px 20px;
    border-radius: 5px;
    font-size: 16px;
    cursor: pointer;
    color: white;
}

button:hover {
    background-color: #5F9EA0; /* Cadet Blue */
    box-shadow: 0 0 10px #FFFFFF;
}
